<script setup lang="ts">
import {ref,onMounted} from 'vue';import {request,upload} from './service';const profile=ref(null),notice=ref('');onMounted(async()=>profile.value=await request('/api/studio/profile'));async function save(){try{profile.value=await request('/api/studio/profile','PUT',profile.value);notice.value='资料已保存';}catch(e){notice.value=e.message;}}async function avatar(e){if(e.target.files[0]){try{profile.value.avatar=(await upload(e.target.files[0])).result.url;}catch(e){notice.value=e.message;}}}async function logout(){await request('/api/logout','POST',{});location.href='/';}
</script>
<template><main class="reader-account"><a href="/">← 回到 Lin 的随手记</a><span>READER'S CORNER</span><h1>很高兴在这里遇见你。</h1><p>这里是你的读者资料。欢迎阅读，也欢迎留下想法，评论会在站主审核后展示。</p><form v-if="profile" @submit.prevent="save"><img :src="profile.avatar" alt="头像"/><label>头像<input type="file" accept="image/png,image/jpeg,image/webp" @change="avatar"/></label><label>昵称<el-input v-model="profile.name" required maxlength="80"/></label><label>简介<el-input v-model="profile.bio" type="textarea" maxlength="1000" :rows="3"/></label><el-button native-type="submit" type="primary">保存资料</el-button><el-button @click="logout">退出登录</el-button><p role="status">{{notice}}</p></form></main></template>
<style scoped>.reader-account{max-width:600px;margin:70px auto;padding:30px}.reader-account>a{font-size:12px}.reader-account>span{display:block;font-size:9px;letter-spacing:3px;margin:60px 0 18px;color:#8c9291}.reader-account h1{font-size:30px;line-height:1.6;margin-bottom:18px}.reader-account p{font-size:13px;line-height:1.9;color:#858993}.reader-account form{padding:30px;background:var(--studio-panel);border-radius:12px;margin-top:30px;border:1px solid var(--studio-line)}.reader-account form img{width:60px;height:60px;object-fit:cover;border-radius:50%;margin-bottom:20px}.reader-account label{display:block;font-size:13px;margin-bottom:24px}.reader-account .el-input,.reader-account .el-textarea{margin-top:10px}</style>
